		// Token: 0x06000180 RID: 384 RVA: 0x0001D918 File Offset: 0x0001BB18
		private int CardWeight(EncounterCard c)
		{
			string iniWeight = c.IniWeight;
			if (iniWeight == "Ambush")
			{
				return this.Config.EncAmbush;
			}
			if (iniWeight == "Riders")
			{
				return this.Config.EncRiders;
			}
			if (iniWeight == "Ahead")
			{
				return this.Config.EncAhead;
			}
			if (iniWeight == "Sniper")
			{
				return this.Config.EncSniper;
			}
			if (!(iniWeight == "Callout"))
			{
				return c.Weight;
			}
			return this.Config.EncCallout;
		}

		// Token: 0x06000181 RID: 385 RVA: 0x0001D9B1 File Offset: 0x0001BBB1
		private int CardChance(EncounterCard c)
		{
			if (c.IniChance == "SkirmishChance")
			{
				return Balance.SkirmishChance;
			}
			if (!(c.IniChance == "ArmyPatrolChance"))
			{
				return c.Chance;
			}
			return Balance.PatrolChance;
		}

